# Binary File Header Parser in C

Here's a complete implementation of a struct and parser for the binary file header with endianness checks and error reporting:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

// Header structure with packed attribute to prevent padding
typedef struct __attribute__((packed)) {
    char magic[4];         // 4 bytes
    uint32_t version;      // 4 bytes
    uint64_t count;        // 8 bytes
} FileHeader;

// Error codes
typedef enum {
    HEADER_OK = 0,
    HEADER_ERR_FILE_NOT_FOUND,
    HEADER_ERR_READ_FAILED,
    HEADER_ERR_INVALID_MAGIC,
    HEADER_ERR_UNSUPPORTED_VERSION,
    HEADER_ERR_ENDIANNES_MISMATCH,
    HEADER_ERR_INVALID_SIZE
} HeaderError;

// Endianness detection (compile-time and runtime)
#if __BYTE_ORDER__ == __ORDER_BIG_ENDIAN__
    #define SYSTEM_IS_BIG_ENDIAN 1
#else
    #define SYSTEM_IS_BIG_ENDIAN 0
#endif

// File endianness (little-endian by default)
#define FILE_IS_LITTLE_ENDIAN 1

// Swap bytes for endianness conversion
static inline uint32_t swap_uint32(uint32_t val) {
    return ((val & 0xFF) << 24) |
           ((val & 0xFF00) << 8) |
           ((val & 0xFF0000) >> 8) |
           ((val & 0xFF000000) >> 24);
}

static inline uint64_t swap_uint64(uint64_t val) {
    return ((val & 0xFF) << 56) |
           ((val & 0xFF00) << 40) |
           ((val & 0xFF0000) << 24) |
           ((val & 0xFF000000) << 8) |
           ((val & 0xFF00000000LL) >> 8) |
           ((val & 0xFF0000000000LL) >> 24) |
           ((val & 0xFF000000000000LL) >> 40) |
           ((val & 0xFF00000000000000LL) >> 56);
}

// Convert from file endianness to system endianness
static void convert_header_to_system_endianness(FileHeader *header, int file_is_big_endian) {
    // Check if conversion is needed
    if ((SYSTEM_IS_BIG_ENDIAN && !file_is_big_endian) || 
        (!SYSTEM_IS_BIG_ENDIAN && file_is_big_endian)) {

        // Magic is byte array, doesn't need conversion
        header->version = swap_uint32(header->version);
        header->count = swap_uint64(header->count);
    }
}

// Convert from system endianness to file endianness (for writing)
static void convert_header_to_file_endianness(FileHeader *header, int file_is_big_endian) {
    // Check if conversion is needed
    if ((SYSTEM_IS_BIG_ENDIAN && !file_is_big_endian) || 
        (!SYSTEM_IS_BIG_ENDIAN && file_is_big_endian)) {

        header->version = swap_uint32(header->version);
        header->count = swap_uint64(header->count);
    }
}

// Initialize header with default values
void init_header(FileHeader *header) {
    memcpy(header->magic, "BIN", 3);  // Example magic
    header->magic[3] = '\0';
    header->version = 1;
    header->count = 0;
}

// Get string representation of error
const char* header_error_string(HeaderError error) {
    switch (error) {
        case HEADER_OK:
            return "Success";
        case HEADER_ERR_FILE_NOT_FOUND:
            return "File not found";
        case HEADER_ERR_READ_FAILED:
            return "Failed to read file";
        case HEADER_ERR_INVALID_MAGIC:
            return "Invalid magic number";
        case HEADER_ERR_UNSUPPORTED_VERSION:
            return "Unsupported version";
        case HEADER_ERR_ENDIANNES_MISMATCH:
            return "Endianness conversion error";
        case HEADER_ERR_INVALID_SIZE:
            return "Invalid file size";
        default:
            return "Unknown error";
    }
}

// Parse header from file
HeaderError parse_header(const char *filename, FileHeader *header) {
    FILE *file;
    size_t bytes_read;
    HeaderError error = HEADER_OK;

    // Check file size
    file = fopen(filename, "rb");
    if (!file) {
        error = HEADER_ERR_FILE_NOT_FOUND;
        goto cleanup;
    }

    // Check file size
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    if (file_size < sizeof(FileHeader)) {
        error = HEADER_ERR_INVALID_SIZE;
        goto cleanup;
    }

    // Read header
    bytes_read = fread(header, 1, sizeof(FileHeader), file);
    if (bytes_read != sizeof(FileHeader)) {
        error = HEADER_ERR_READ_FAILED;
        goto cleanup;
    }

    // Validate magic
    if (memcmp(header->magic, "BIN", 3) != 0) {
        error = HEADER_ERR_INVALID_MAGIC;
        goto cleanup;
    }

    // Validate version (example: only version 1 is supported)
    if (header->version != 1) {
        error = HEADER_ERR_UNSUPPORTED_VERSION;
        goto cleanup;
    }

    // Handle endianness (file is assumed little-endian)
    convert_header_to_system_endianness(header, FILE_IS_LITTLE_ENDIAN ? 0 : 1);

cleanup:
    if (file) {
        fclose(file);
    }

    if (error != HEADER_OK) {
        fprintf(stderr, "Error parsing header: %s\n", header_error_string(error));
    }

    return error;
}

// Write header to file
HeaderError write_header(const char *filename, const FileHeader *header) {
    FILE *file;
    size_t bytes_written;
    HeaderError error = HEADER_OK;
    FileHeader write_header;

    // Copy header for modification
    write_header = *header;

    // Handle endianness (convert to file endianness before writing)
    convert_header_to_file_endianness(&write_header, FILE_IS_LITTLE_ENDIAN ? 0 : 1);

    file = fopen(filename, "wb");
    if (!file) {
        error = HEADER_ERR_FILE_NOT_FOUND;
        goto cleanup;
    }

    bytes_written = fwrite(&write_header, 1, sizeof(FileHeader), file);
    if (bytes_written != sizeof(FileHeader)) {
        error = HEADER_ERR_READ_FAILED;
        goto cleanup;
    }

cleanup:
    if (file) {
        fclose(file);
    }

    if (error != HEADER_OK) {
        fprintf(stderr, "Error writing header: %s\n", header_error_string(error));
    }

    return error;
}

// Print header information
void print_header(const FileHeader *header) {
    printf("File Header Information:\n");
    printf("  Magic:      %.4s\n", header->magic);
    printf("  Version:    %u\n", header->version);
    printf("  Count:      %lu\n", (unsigned long)header->count);
    printf("  System is:  %s-endian\n", SYSTEM_IS_BIG_ENDIAN ? "big" : "little");
    printf("  File is:    %s-endian\n", FILE_IS_LITTLE_ENDIAN ? "little" : "big");
}

// Example usage
int main(int argc, char *argv[]) {
    FileHeader header;
    HeaderError error;

    if (argc < 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        printf("Example creates 'test.bin' if it doesn't exist.\n");

        // Create example file
        init_header(&header);
        header.count = 42;
        error = write_header("test.bin", &header);

        if (error != HEADER_OK) {
            return 1;
        }

        printf("Created test.bin with example header.\n\n");

        // Now parse it
        error = parse_header("test.bin", &header);

        if (error == HEADER_OK) {
            print_header(&header);
        }

        return error;
    }

    error = parse_header(argv[1], &header);

    if (error == HEADER_OK) {
        print_header(&header);

        // Example: Modify and write back
        header.count += 1;
        error = write_header(argv[1], &header);

        if (error == HEADER_OK) {
            printf("\nSuccessfully updated count to %lu\n", (unsigned long)header.count);
        }
    }

    return error;
}
```

## Key Features:

1. **Packed Struct**: Uses `__attribute__((packed))` to prevent compiler padding
2. **Endianness Handling**:
   - Compile-time detection using `__BYTE_ORDER__`
   - Runtime conversion functions for 32-bit and 64-bit integers
   - Separate conversion for reading and writing

3. **Error Handling**:
   - Comprehensive error codes with descriptions
   - Proper error propagation through return values
   - File validation checks (size, read operations)

4. **Core Functions**:
   - `parse_header()`: Reads and validates header from file
   - `write_header()`: Writes header to file with endianness conversion
   - `print_header()`: Displays header information
   - `init_header()`: Initializes header with default values

