Here's a comprehensive error-handling pattern using the goto-based cleanup idiom in C:

```c
#include <stdio.h>
#include <stdlib.h>

char* read_file_data(const char* filename, size_t buffer_size) {
    // Step 1: Declare and initialize all resources to NULL/0
    FILE* file = NULL;
    char* buffer = NULL;
    size_t bytes_read = 0;

    // Step 2: Attempt each operation with error checking
    // If any step fails, we goto the cleanup label

    // Open the file
    file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        goto cleanup;
    }

    // Allocate the buffer
    buffer = malloc(buffer_size);
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate buffer of size %zu\n", buffer_size);
        goto cleanup;
    }

    // Read from the file
    bytes_read = fread(buffer, 1, buffer_size, file);
    if (bytes_read != buffer_size) {
        if (feof(file)) {
            fprintf(stderr, "Unexpected end of file. Read %zu of %zu bytes\n", 
                    bytes_read, buffer_size);
        } else {
            fprintf(stderr, "Error reading from file: %s\n", filename);
        }
        goto cleanup;
    }

    // Step 3: Success path - close file but return buffer
    fclose(file);
    return buffer;

cleanup:
    // Step 4: Cleanup all resources in reverse order
    // Each resource is checked before being freed (handles cases where
    // we jump to cleanup before the resource was allocated)

    // Free the buffer if it was allocated
    if (buffer != NULL) {
        free(buffer);
        buffer = NULL;  // Optional: prevents double-free if needed later
    }

    // Close the file if it was opened
    if (file != NULL) {
        fclose(file);
        file = NULL;    // Optional: prevents double-close if needed later
    }

    // Return NULL to indicate failure
    return NULL;
}

// Alternative pattern with nested goto labels for different cleanup stages
char* read_file_data_nested(const char* filename, size_t buffer_size) {
    FILE* file = NULL;
    char* buffer = NULL;

    // Open file
    file = fopen(filename, "rb");
    if (file == NULL) {
        goto error_no_resources;
    }

    // Allocate buffer
    buffer = malloc(buffer_size);
    if (buffer == NULL) {
        goto error_with_file;
    }

    // Read data
    size_t bytes_read = fread(buffer, 1, buffer_size, file);
    if (bytes_read != buffer_size) {
        goto error_with_buffer;
    }

    // Success: return buffer and close file
    fclose(file);
    return buffer;

error_with_buffer:
    // Cleanup buffer
    free(buffer);
    buffer = NULL;

error_with_file:
    // Cleanup file
    fclose(file);
    file = NULL;

error_no_resources:
    // No resources to clean up, just return NULL
    return NULL;
}

// More complex example with multiple buffers and error messages
typedef struct {
    char* data;
    size_t size;
    char* metadata;
} FileData;

FileData* process_file(const char* filename) {
    FileData* result = NULL;
    FILE* file = NULL;
    char* data_buffer = NULL;
    char* metadata_buffer = NULL;
    long file_size = 0;

    // Allocate result structure
    result = malloc(sizeof(FileData));
    if (result == NULL) {
        fprintf(stderr, "Failed to allocate result structure\n");
        goto cleanup;
    }
    result->data = NULL;
    result->metadata = NULL;
    result->size = 0;

    // Open file
    file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        goto cleanup;
    }

    // Get file size
    fseek(file, 0, SEEK_END);
    file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (file_size < 0) {
        fprintf(stderr, "Failed to determine file size\n");
        goto cleanup;
    }

    // Allocate data buffer
    data_buffer = malloc((size_t)file_size);
    if (data_buffer == NULL) {
        fprintf(stderr, "Failed to allocate data buffer\n");
        goto cleanup;
    }

    // Allocate metadata buffer (separate allocation)
    metadata_buffer = malloc(1024);
    if (metadata_buffer == NULL) {
        fprintf(stderr, "Failed to allocate metadata buffer\n");
        goto cleanup;
    }

    // Read main data
    size_t bytes_read = fread(data_buffer, 1, (size_t)file_size, file);
    if (bytes_read != (size_t)file_size) {
        fprintf(stderr, "Failed to read complete file data\n");
        goto cleanup;
    }

    // Read metadata (assuming it's at the end)
    fseek(file, 0, SEEK_SET);  // Simplified: in reality might be different
    fread(metadata_buffer, 1, 1024, file);

    // Success: populate result and clean up local resources
    result->data = data_buffer;
    data_buffer = NULL;  // Transfer ownership
    result->metadata = metadata_buffer;
    metadata_buffer = NULL;  // Transfer ownership
    result->size = (size_t)file_size;

    fclose(file);
    return result;

cleanup:
    // Cleanup in reverse order of allocation

    if (metadata_buffer != NULL) {
        free(metadata_buffer);
        metadata_buffer = NULL;
    }

    if (data_buffer != NULL) {
        free(data_buffer);
        data_buffer = NULL;
    }

    if (file != NULL) {
        fclose(file);
        file = NULL;
    }

    if (result != NULL) {
        // Don't free result->data or result->metadata if they weren't set
        free(result);
        result = NULL;
    }

    return NULL;
}

int main() {
    // Example usage
    char* data = read_file_data("example.txt", 4096);
    if (data == NULL) {
        fprintf(stderr, "Failed to read file\n");
        return 1;
    }

    // Process data...
    printf("Successfully read file data\n");

    // Cleanup
    free(data);

    return 0;
}
```

## Key Patterns Explained:

1. **Initialize to NULL**: All pointers are initialized to `NULL` before use, so we can safely check them in cleanup.

2. **Single cleanup label**: The `cleanup:` label handles freeing all resources. Each resource is checked before being freed, allowing us to jump to cleanup at any point.

3. **Cleanup in reverse order**: Resources are freed in the opposite order they were allocated. This is particularly important when resources depend on each other.

4. **Set to NULL after free**: Optional but helpful pattern to prevent double-free bugs and make debugging easier.

5. **Return ownership transfer**: When transferring ownership (like returning a buffer), set the local pointer to `NULL` after assigning it to the result.

## Advantages of goto Cleanup:

- **No nested if-else**: Avoids deeply nested error handling blocks
- **Single cleanup path**: All cleanup happens in one place, reducing code duplication
- **Easy to extend**: Adding new resource allocations only requires adding one more check before cleanup
- **Memory safe**: Ensures no resource leaks regardless of where an error occurs
- **Performance**: Minimal runtime overhead compared to other error-handling mechanisms

## When to Use:

- Functions with multiple resource allocations
- Critical system code where resource leaks are unacceptable
- Code that must maintain consistent state even on errors
- When you want explicit, predictable cleanup paths

