    size_t length;   /* number of characters consumed from the buffer */
} greedy_match_result_t;

/*
 * Greedily matches the longest token from `vocabulary` that appears as a
 * prefix at the very start of `buffer`.
 *
 * @param buffer       the text buffer to match against (not required to be
 *                     null-terminated; `buffer_size` limits the read window)
 * @param buffer_size  number of characters available in `buffer`
 * @param vocabulary   array of null-terminated token strings
 * @param vocab_size   number of tokens in the vocabulary
 * @return             struct with the matching token's id (vocabulary index)
 *                     and the length consumed. id=-1, length=0 if nothing matches.
 *
 * Greedy strategy: among all tokens that match the buffer prefix, the longest
 * one wins. If multiple tokens share the same maximum length, the first one
 * encountered in the vocabulary array is kept.
 */
greedy_match_result_t greedy_match_longest_token(
    const char* buffer, size_t buffer_size,
    const char** vocabulary, size_t vocab_size)
